  | { type: 'run_stopped'; reason: 'user' | 'signal' | 'evaluation_failure' | 'storage_error'; resumable: boolean; repositorySnapshotHash?: string }
  | { type: 'run_finished' }
  | { type: 'iteration_limit' }
